effect.shader:
float luma(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }

void main() {
    vec2 uv = acScreenNorm;
    vec2 t = thickness / acResolution;

    float tl = luma(texture(inputImg, uv + vec2(-t.x,  t.y)).rgb);
    float  l = luma(texture(inputImg, uv + vec2(-t.x,  0.0)).rgb);
    float bl = luma(texture(inputImg, uv + vec2(-t.x, -t.y)).rgb);
    float tt = luma(texture(inputImg, uv + vec2( 0.0,  t.y)).rgb);
    float bb = luma(texture(inputImg, uv + vec2( 0.0, -t.y)).rgb);
    float tr = luma(texture(inputImg, uv + vec2( t.x,  t.y)).rgb);
    float  r = luma(texture(inputImg, uv + vec2( t.x,  0.0)).rgb);
    float br = luma(texture(inputImg, uv + vec2( t.x, -t.y)).rgb);

    float gx = -tl - 2.0 * l - bl + tr + 2.0 * r + br;
    float gy = -tl - 2.0 * tt - tr + bl + 2.0 * bb + br;
    float g = sqrt(gx * gx + gy * gy);
    float m = smoothstep(threshold, threshold + 0.1, g);

    vec4 base = texture(inputImg, uv);
    vec4 bg = mix(bgColor, base, mistura);
    vec3 col = mix(bg.rgb, edgeColor.rgb, m);
    float a = mix(bg.a, edgeColor.a, m);
    fragColor = vec4(col, a);
}
